/// `contextTokens > contextWindow - reserveTokens`.
bool shouldCompact(
  int contextTokens,
  int contextWindow,
  CompactionSettings settings,
) {
  if (!settings.enabled) return false;
  return contextTokens > contextWindow - settings.reserveTokens;
